package com.andresps.gdsmock.inventory.domain.generator;

import static org.assertj.core.api.Assertions.assertThat;

import com.andresps.gdsmock.inventory.domain.model.Airport;
import java.time.Instant;
import java.time.ZoneId;
import java.time.zone.ZoneOffsetTransition;
import java.time.zone.ZoneRules;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * The catalog only uses time zones whose rules are stable across tzdata versions, so a feed generated by one JVM
 * converts back to the same instants on another (Mock-Gamma sends local times + zone, Mock-Beta offsets). Tzdata 2026,
 * for example, moved {@code Africa/Casablanca} from UTC+1 to UTC+0: fixtures recorded on an older JDK stopped
 * reconciling on a newer one.
 *
 * <p>"Stable" is checked through a proxy that any tzdata version can evaluate: a zone either has a fixed offset with no
 * transition since {@link #STABLE_SINCE}, or follows recurring annual DST rules (EU/US/AU style) whose explicit
 * history ended before that date. Zones whose rules were changed recently (abolished or permanent DST, per-year
 * transitions such as Morocco's Ramadan rules) fail both.
 */
class CatalogTimeZonesTest {

    /** Ten years before the default reference date: rules untouched for a decade are unlikely to change. */
    private static final Instant STABLE_SINCE = Instant.parse("2016-01-01T00:00:00Z");

    @Test
    @DisplayName("Every catalog zone has rules stable across tzdata versions (fixed offset or recurring annual DST)")
    void catalogUsesStableZones() {
        List<String> volatileZones = Catalog.AIRPORTS.stream()
                .map(Airport::zone)
                .distinct()
                .filter(zone -> !isStable(zone))
                .map(ZoneId::getId)
                .toList();

        assertThat(volatileZones)
                .as("zones whose rules changed recently or are defined year by year")
                .isEmpty();
    }

    @Test
    @DisplayName("The stability check rejects zones whose rules changed recently")
    void proxyRejectsKnownVolatileZones() {
        assertThat(isStable(ZoneId.of("America/Mexico_City")))
                .as("DST abolished in 2022")
                .isFalse();
        assertThat(isStable(ZoneId.of("America/Sao_Paulo")))
                .as("DST abolished in 2019")
                .isFalse();
        assertThat(isStable(ZoneId.of("Europe/Istanbul")))
                .as("permanent +3 since 2016")
                .isFalse();
        assertThat(isStable(ZoneId.of("Africa/Casablanca")))
                .as("year-by-year rules, changed in 2026")
                .isFalse();
        assertThat(isStable(ZoneId.of("Europe/Madrid"))).as("EU rules").isTrue();
        assertThat(isStable(ZoneId.of("Asia/Tokyo")))
                .as("fixed offset since 1951")
                .isTrue();
    }

    static boolean isStable(ZoneId zone) {
        ZoneRules rules = zone.getRules();
        if (rules.getTransitionRules().isEmpty()) {
            return rules.nextTransition(STABLE_SINCE) == null;
        }
        List<ZoneOffsetTransition> history = rules.getTransitions();
        return history.isEmpty() || history.getLast().getInstant().isBefore(STABLE_SINCE);
    }
}
